// ===============================
// 1. OBTENER ITEMS Y FILTRAR PREGUNTAS
// ===============================
let items = $input.all();
items = items.filter(i => i.json.pregunta);
items = items.filter((item, index, arr) =>
  index === arr.findIndex(t => t.json.id_detalle === item.json.id_detalle)
);
items.sort((a, b) => (a.json.id_detalle > b.json.id_detalle ? 1 : -1));

// ===============================
// 2. OBTENER RESUMEN
// ===============================
const allInputs = $input.all();
const resumenItem = allInputs.find(i => i.json.nota_final);

let nombre_estudiante = "Estudiante";
try {
  const nodoNombre = $('Normalizador_respuestas').first();
  if (nodoNombre && nodoNombre.json.nombre_completo) {
    nombre_estudiante = nodoNombre.json.nombre_completo;
  }
} catch (e) {}

// Resumen (pero usando el nombre real)
const resumen = resumenItem ? resumenItem.json : {};
resumen.nombre_estudiante = nombre_estudiante;


// ===============================
// 3. NORMALIZACIÓN
// ===============================
function normalize(str) {
  return (str || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/^correcta:\s*/i, "")
    .replace(/^✔\s*/i, "")
    .replace(/\s+/g, " ");
}

for (const item of items) {
  const data = item.json;
  data.originalUsuario = data.respuesta_usuario || "";
  data.originalCorrecta = data.respuesta_correcta || "";
  data.usuarioLimpio = normalize(data.respuesta_usuario);
  data.correctaLimpia = normalize(data.respuesta_correcta);
  data.esCorrectaReal = data.usuarioLimpio === data.correctaLimpia;
}

// ===============================
// 4. CÁLCULOS
// ===============================
const total = items.length;
const correctas = items.filter(item => item.json.esCorrectaReal).length;
const porcentaje = total > 0 ? ((correctas / total) * 100).toFixed(0) : 0;

// ===============================
// 5. GENERAR HTML FINAL
// ===============================
let htmlPdf = `
<html>
<head>
<style>

  /* Márgenes de página */
  @page {
    margin-top: 40px;
    margin-bottom: 40px;
  }

  body {
    font-family: Helvetica, Arial, sans-serif;
    padding: 40px 60px;
    font-size: 14px;
    color: #333;
    line-height: 1.6;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  h1 {
    font-size: 26px;
    margin-bottom: 12px;
    font-weight: 600;
  }

  h2 {
    font-size: 20px;
    font-weight: 600;
    margin-top: 35px;
    margin-bottom: 20px;
  }

  /* Información del estudiante */
  .header-info { margin-bottom: 25px; font-size: 15px; }
  .header-info div { margin-bottom: 4px; }

  .header-info strong {
    display: inline-block;
    min-width: 85px;
  }

  /* Caja Resumen */
  .stats-box {
    border: 1px solid #ddd;
    padding: 18px 22px;
    background: #fafafa;
    border-radius: 8px;
    margin-bottom: 35px;
    break-inside: avoid;
  }

  .stats-box p strong {
    font-size: 16px;
    color: #007bff;
  }

  /* ========================= */
  /*   CONTENEDOR DE PREGUNTA  */
  /* ========================= */

  .pregunta-container {
    padding-top: 10px;
    padding-bottom: 22px;
    border-bottom: 1px solid #e5e5e5;
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .pregunta-container:last-child {
    border-bottom: none;
  }

  .pregunta-titulo {
    font-weight: 600;
    font-size: 15px;
    margin-bottom: 6px;
    display: block;
  }


  .pregunta-incorrecta {
      background: #ffecec; /* rojo muy suave */
      border-left: 4px solid #d9534f; /* rojo fuerte */
      padding: 18px 18px 22px 18px;
      border-radius: 6px;
      margin-bottom: 30px;
      margin-top: 25px;

      break-inside: avoid;
      page-break-inside: avoid;
  }

  /* El título mantiene el estilo normal, solo reforzamos color */
  .pregunta-incorrecta .pregunta-titulo {
      color: #333333; 
      font-weight: 700;
      margin-bottom: 10px;
  }


  .status-correcta {
    color: #28a745;
    font-weight: 600;
    margin-top: 6px;
  }

  .status-incorrecta {
    color: #d9534f;
    font-weight: 600;
    margin-top: 6px;
  }

  .respuesta-correcta-esperada {
    margin-top: 8px;
    font-size: 14px;
  }

  .explicacion-box {
    background: #fff7d6;
    border-left: 4px solid #ffc34d;
    padding: 12px;
    margin-top: 12px;
    border-radius: 4px;
    font-size: 13px;
    break-inside: avoid;
  }

</style>
</head>

<body>

<h1>Reporte de Evaluación</h1>

<div class="header-info">
  <div><strong>Estudiante:</strong> ${resumen.nombre_estudiante}</div>
  <div><strong>Correo:</strong> ${resumen.correo}</div>
</div>

<div class="stats-box">
  <h3>Resumen de Resultados</h3>
  <p><strong>Nota Final:</strong> ${resumen.nota_final}</p>
  <p><strong>Acierto:</strong> ${porcentaje}% (${correctas}/${total})</p>
</div>

<h2>Detalle de respuestas:</h2>
`;

// ===============================
// 6. PREGUNTAS
// ===============================
for (const item of items) {
  const data = item.json;

  const className = data.esCorrectaReal
    ? "pregunta-container"
    : "pregunta-container pregunta-incorrecta";

  htmlPdf += `<div class="${className}">`;

  htmlPdf += `<span class="pregunta-titulo">${data.pregunta}</span>`;
  htmlPdf += `<div class="respuesta-usuario"><strong>Tu respuesta:</strong> ${data.originalUsuario}</div>`;

  if (data.esCorrectaReal) {
    htmlPdf += `<div class="status-correcta">✅ Correcto</div>`;
  } else {
    htmlPdf += `<div class="status-incorrecta">❌ Incorrecto</div>`;
    htmlPdf += `<div class="respuesta-correcta-esperada"><strong>Correcta:</strong> ${data.originalCorrecta}</div>`;

    if (data.explicacion) {
      htmlPdf += `
        <div class="explicacion-box">
          <strong>Explicación:</strong> ${data.explicacion}
        </div>`;
    }
  }

  htmlPdf += `</div>`;
}

htmlPdf += `</body></html>`;

// ===============================
// 7. RETORNAR
// ===============================
return [{
  json: {
    emailTo: resumen.correo,
    emailSubject: `Resultados Evaluación: ${resumen.nota_final}`,
    emailBody: `
      Hola,<br><br>
      Tu evaluación ha sido revisada.<br><br>
      <strong>Nota Final:</strong> ${resumen.nota_final}<br>
      <strong>Acierto:</strong> ${porcentaje}% (${correctas}/${total})<br><br>
      Se adjunta el PDF con el desglose completo.<br><br>
      Saludos.
    `,
    pdfHtml: htmlPdf,
    pdfFileName: `Feedback_${resumen.id_evaluacion}.pdf`
  }
}];

// Obtenemos los datos del nodo anterior
const items = $input.all();

// Recorremos los items (usualmente es solo 1)
for (const item of items) {
  // Obtenemos el texto Base64 del PDF
  const base64String = item.json.response;

  // Creamos la estructura binaria que n8n necesita para los archivos
  item.binary = {
    data: {
      data: base64String,
      mimeType: 'application/pdf',
      fileName: 'Feedback_Evaluacion.pdf' // Puedes cambiar el nombre aquí si quieres
    }
  };
}

return items;

// Respuestas que vienen del webhook normalizado
const respuestas = $input.all().map(item => item.json);

// Banco de preguntas desde el otro input (nodo "Banco preguntas")
const banco = $items('Banco preguntas').map(item => item.json);

// Helper para normalizar texto (opcional, para evitar problemas de espacios/mayúsculas)
function norm(str) {
  return String(str || '')
    .trim()
    .toLowerCase();
}

// Índice de preguntas del banco: clave = id_evaluacion + pregunta_normalizada
const indexBanco = new Map();

for (const q of banco) {
  const idEval = String(q.id_evaluacion || '').trim();
  const preguntaNorm = norm(q.pregunta);
  const key = `${idEval}|||${preguntaNorm}`;
  indexBanco.set(key, q);

  // Fallback: si no tiene id_evaluacion en el banco, también indexamos sin ID
  if (!idEval) {
    const keySinEval = `|||${preguntaNorm}`;
    if (!indexBanco.has(keySinEval)) {
      indexBanco.set(keySinEval, q);
    }
  }
}

const salida = [];

for (const r of respuestas) {
  const correo = r.correo;
  const id_evaluacion = r.id_evaluacion;
  const id_intento = r.id_intento;
  const nombre_completo = r.nombre_completo;

  // 👇 Si no hay correo, lo saltamos (por seguridad, igual que antes)
  if (!correo) {
    continue;
  }

  const preguntaOriginal = String(r.pregunta || "").trim();
  const preguntaNorm = norm(preguntaOriginal);

  // Usa respuesta_usuario si existe, si no, respuesta (como antes)
  const respuestaUsuario = String(
    r.respuesta_usuario ?? r.respuesta ?? ""
  ).trim();

  // Buscamos en el índice usando id_evaluacion + pregunta
  const keyConEval = `${String(id_evaluacion || '').trim()}|||${preguntaNorm}`;
  let registroBanco = indexBanco.get(keyConEval);

  // Si no encontramos con id_evaluacion, probamos sin id_evaluacion
  if (!registroBanco) {
    const keySinEval = `|||${preguntaNorm}`;
    registroBanco = indexBanco.get(keySinEval);
  }

  let respuestaCorrectaTexto = "No encontrada";
  let estado = "Incorrecta";
  let explicacion = "";

  if (registroBanco) {
    // Tu lógica original: respuesta_correcta es una LETRA (A/B/C/D)
    const letra = String(registroBanco.respuesta_correcta || "")
      .trim()
      .toUpperCase();
    const campo = "alt_" + letra;

    const valorAlt = registroBanco[campo];
    const valorAltStr =
      valorAlt === undefined || valorAlt === null ? "" : String(valorAlt);

    respuestaCorrectaTexto = valorAltStr.trim() || "No encontrada";

    explicacion = registroBanco.explicacion
      ? String(registroBanco.explicacion)
      : "";

    if (
      respuestaUsuario !== "" &&
      respuestaCorrectaTexto !== "No encontrada" &&
      respuestaUsuario === respuestaCorrectaTexto
    ) {
      estado = "Correcta";
    }
  }

  salida.push({
    json: {
      // 🔹 Nuevos campos que propagamos
      id_evaluacion,
      id_intento,
      nombre_completo,

      // 🔹 Campos que ya tenías
      correo,
      pregunta: preguntaOriginal,
      respuesta_usuario: respuestaUsuario,
      respuesta_correcta: respuestaCorrectaTexto,
      estado,
      explicacion,
    },
  });
}

return salida;

// =======================================
// 1. Obtener todas las filas del desglose
// =======================================
const desglose = $input.all().map(item => item.json);

// Agrupación por evaluación + intento + correo
const porIntento = {};

function normEstado(str) {
  return String(str || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

for (const fila of desglose) {
  const id_evaluacion = fila.id_evaluacion || '';
  const id_intento = fila.id_intento || '';
  const correo = fila.correo || '';
  const nombre_completo = fila.nombre_completo || '';

  const key = `${id_evaluacion}||${id_intento}||${correo}`;

  if (!porIntento[key]) {
    porIntento[key] = {
      id_evaluacion,
      id_intento,
      correo,
      nombre_completo,
      total_preguntas: 0,
      respuestas_correctas: 0,
    };
  }

  porIntento[key].total_preguntas += 1;

  // Estado normalizado
  const estado = normEstado(fila.estado);

  if (estado === "correcta" || estado === "correcto") {
    porIntento[key].respuestas_correctas += 1;
  }
}

// ===============================
// 2. Construcción del resumen final
// ===============================
const salida = [];

for (const key in porIntento) {
  const data = porIntento[key];

  const porcentaje =
    data.total_preguntas > 0
      ? (data.respuestas_correctas / data.total_preguntas) * 100
      : 0;

  // Nota final 1–7
  const nota_final = (1 + (porcentaje / 100) * 6).toFixed(2);

  salida.push({
    json: {
      id_evaluacion: data.id_evaluacion,
      id_intento: data.id_intento,
      correo: data.correo,
      nombre_completo: data.nombre_completo,
      total_preguntas: data.total_preguntas,
      respuestas_correctas: data.respuestas_correctas,
      porcentaje_aciertos: porcentaje, // AHORA ES NÚMERO REAL
      nota_final,
      tipo: "resumen"
    },
  });
}

return salida;

// Entrada: 1 item desde el Webhook
const root    = items[0].json;
// Si viene anidado en body (Webhook), lo tomamos de ahí
const entrada = root.body || root;

const id_evaluacion  = entrada.id_evaluacion;
const id_intento     = entrada.id_intento;
const email          = entrada.email;
const nombreCompleto = entrada.nombre_completo;
const respuestas     = entrada.respuestas || {};

// Campos que NO queremos tratar como preguntas
const camposIgnorar = new Set([
  'Nombre Completo',
  'Marca temporal',
  'Dirección de correo electrónico',
  'Puntuación', // por si algún día aparece
]);

const salida = [];

// Recorremos todas las claves del objeto "respuestas"
for (const tituloPregunta of Object.keys(respuestas)) {
  if (camposIgnorar.has(tituloPregunta)) continue;

  // Cada entrada es un array, nos quedamos con la primera respuesta
  const respuestaArray = respuestas[tituloPregunta] || [];
  const respuestaUsuario = respuestaArray.length > 0
    ? String(respuestaArray[0]).trim()
    : '';

  salida.push({
    json: {
      id_evaluacion,
      id_intento,
      correo: email,
      nombre_completo: nombreCompleto,
      pregunta: tituloPregunta,
      respuesta_usuario: respuestaUsuario,
      // estos los completa luego el comparador:
      // respuesta_correcta,
      // estado,
      // explicacion,
    },
  });
}

return salida;

const respuestas = $input.all().map(i => i.json);
const salida = [];

for (let idx = 0; idx < respuestas.length; idx++) {
  const r = respuestas[idx];

  const id_evaluacion = r.id_evaluacion;
  const id_intento = r.id_intento;
  const correo = r.correo;

  // ID único por detalle (pregunta dentro del intento)
  const id_detalle = `${id_intento}_${idx + 1}`;

  salida.push({
    json: {
      id_evaluacion,
      id_intento,
      id_detalle,
      correo,
      pregunta: r.pregunta,
      respuesta_usuario: r.respuesta_usuario,
      respuesta_correcta: r.respuesta_correcta,
      estado: r.estado,
      explicacion: r.explicacion,
    },
  });
}

return salida;

const items = $input.all();


const salida = [];

for (const item of items) {
  const data = item.json;

  // Verificamos si la respuesta es correcta
  const esCorrecta = data.respuesta_usuario === data.respuesta_correcta;

  if (esCorrecta) {
    // Eliminamos la explicación si es correcta
    delete data.explicacion;
  }

  // Agregamos el item modificado a la salida
  salida.push({ json: data });
}

return salida;
